	public static void main(String[] args) {
		int[] coll = new int[4096];
		int gamma = 0x40000001, idx = 0;
		for (int i = 0; i < 64; i++) {
			for (int j = 0; j < 0x8000000 && idx < 4096; j++, gamma += 2) {
//			for (int j = 0; j < 0x8000000 && idx < 4096; j++, gamma = gamma * 333333333 + 555555555) {
				int score = sumGamma(gamma);
				if(score == 2 && rateGamma(gamma) == 1) coll[idx++] = gamma;
			}
			System.out.println("Finished " + (i + 1) + "/64");
		}
		if(idx < 4096){
			System.out.println("UH OH! Not enough good gammas!");
			System.exit(1);
		}
		idx = 0;
		System.out.println("new int[] {");
		for (int y = 0; y < 512; y++) {
			for (int x = 0; x < 8; x++) {
				System.out.printf("0x%08X, ", coll[idx++]);
			}
			System.out.println();
		}
		System.out.println("}");
	}

